{
  "skill": "run-dev-graph-system-spec",
  "loop": 1,
  "decision": "fail-closed",
  "checklist": [
    {
      "id": "system_spec_root_containment",
      "text": "system_spec content root が caller repo 内で repository_id/common-dir と一致する",
      "status": "PASS",
      "evidence": "C24 resolve-repo-context.py --mode write receipt: repo_root == content_roots.repository, repository_id local:sha256:eff68b20…, git_common_dir が repo 直下 .git、system_spec realpath は repo 内 (symlink なし)"
    },
    {
      "id": "harness_preflight",
      "text": "system-spec-harness が version >=0.1.0 <1.0.0 と required 4 entry points を満たす",
      "status": "PASS",
      "evidence": "plugin.json name=system-spec-harness version=0.1.14、package-contract.json#entry_points.skills に run-system-spec-elicit / run-system-spec-doc-fetch / run-system-spec-compile / assign-system-spec-completeness-evaluator が実在"
    },
    {
      "id": "delegation_via_harness_skills",
      "text": "elicit/条件付き doc-fetch/compile/evaluator が system-spec-harness Skill 経由だけで実行される",
      "status": "BLOCKED",
      "evidence": "R2-delegate の入力契約 (PASS preflight, spec state, user answers, doc-fetch 必要性) のうち spec state が未達。graph は system-spec-harness 由来の confirmed import 2件を主張するが、content authority である system_spec root は空で参照先が解決できない。未解決 lineage を残したまま新規 elicit/compile を走らせると、確定済みと主張される章の出典を事後捏造することになるため委譲を開始しない。"
    },
    {
      "id": "gates_pass",
      "text": "coverage/source-citation/evaluator gate が全て PASS である",
      "status": "BLOCKED",
      "evidence": "delegation 未実行のため gate 未取得。部分成功を PASS にしない (Layer 4)。"
    },
    {
      "id": "lineage_complete",
